
import http from "node:http";
import WebSocket, { WebSocketServer } from "ws";

const PORT = Number(process.env.PORT || 3000);
const APP_ID = process.env.DERIV_APP_ID || "1089";

const DERIV_URL =
  `wss://ws.derivws.com/websockets/v3?app_id=${APP_ID}`;

  const MARKETS = (
    process.env.MARKETS ||
      "R_10,R_25,R_50,R_75,R_100,1HZ10V,1HZ25V,1HZ50V,1HZ75V,1HZ100V"
      ).split(",").map(s => s.trim()).filter(Boolean);

      const ACCESS_KEY = process.env.INGESTION_ACCESS_KEY || "";

      const history = new Map();
      const pipSizes = new Map();

      for (const symbol of MARKETS) {
        history.set(symbol, []);
        }

        let deriv;
        let connected = false;
        let reconnectTimer;
        let reconnectDelay = 1000;
        let reconnects = 0;
        let lastMessageAt = null;

        const clients = new Set();
        const authenticated = new WeakSet();

        function lastDigit(quote, pipSize) {
          const decimals = Number.isInteger(pipSize)
              ? pipSize
                  : 2;

                    const formatted = Number(quote).toFixed(decimals);
                      return Number(formatted.replace(".", "").slice(-1));
                      }

                      function sendJSON(socket, data) {
                        if (socket.readyState === WebSocket.OPEN) {
                            socket.send(JSON.stringify(data));
                              }
                              }

                              function broadcast(data) {
                                for (const client of clients) {
                                    if (!ACCESS_KEY || authenticated.has(client)) {
                                          sendJSON(client, data);
                                              }
                                                }
                                                }

                                                function saveTick(symbol, quote, epoch, pipSize) {
                                                  const tick = {
                                                      symbol,
                                                          quote: Number(quote),
                                                              epoch: Number(epoch),
                                                                  pip_size: pipSize,
                                                                      digit: lastDigit(quote, pipSize),
                                                                          received_at: Date.now()
                                                                            };

                                                                              const buffer = history.get(symbol);
                                                                                if (!buffer) return;

                                                                                  buffer.push(tick);

                                                                                    if (buffer.length > 1000) {
                                                                                        buffer.shift();
                                                                                          }

                                                                                            lastMessageAt = Date.now();

                                                                                              broadcast({
                                                                                                  type: "tick",
                                                                                                      data: tick
                                                                                                        });
                                                                                                        }

                                                                                                        function connectDeriv() {
                                                                                                          clearTimeout(reconnectTimer);

                                                                                                            console.log("Connecting to Deriv...");

                                                                                                              deriv = new WebSocket(DERIV_URL);

                                                                                                                deriv.on("open", () => {
                                                                                                                    connected = true;
                                                                                                                        reconnectDelay = 1000;

                                                                                                                            console.log("Connected to Deriv.");

                                                                                                                                for (const symbol of MARKETS) {
                                                                                                                                      deriv.send(JSON.stringify({
                                                                                                                                              ticks_history: symbol,
                                                                                                                                                      count: 1000,
                                                                                                                                                              end: "latest",
                                                                                                                                                                      style: "ticks",
                                                                                                                                                                              subscribe: 1
                                                                                                                                                                                    }));
                                                                                                                                                                                        }

                                                                                                                                                                                            broadcast({ type: "status", connected: true });
                                                                                                                                                                                              });

                                                                                                                                                                                                deriv.on("message", raw => {
                                                                                                                                                                                                    let message;

                                                                                                                                                                                                        try {
                                                                                                                                                                                                              message = JSON.parse(raw.toString());
                                                                                                                                                                                                                  } catch {
                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                if (message.error) {
                                                                                                                                                                                                                                      console.error("Deriv API:", message.error.message);
                                                                                                                                                                                                                                            broadcast({
                                                                                                                                                                                                                                                    type: "api_error",
                                                                                                                                                                                                                                                            message: message.error.message
                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                const symbol =
                                                                                                                                                                                                                                                                                      message.tick?.symbol ||
                                                                                                                                                                                                                                                                                            message.echo_req?.ticks_history;

                                                                                                                                                                                                                                                                                                if (!symbol || !history.has(symbol)) return;

                                                                                                                                                                                                                                                                                                    const pipSize =
                                                                                                                                                                                                                                                                                                          message.tick?.pip_size ??
                                                                                                                                                                                                                                                                                                                message.pip_size ??
                                                                                                                                                                                                                                                                                                                      pipSizes.get(symbol) ??
                                                                                                                                                                                                                                                                                                                            2;

                                                                                                                                                                                                                                                                                                                                pipSizes.set(symbol, pipSize);

                                                                                                                                                                                                                                                                                                                                    if (message.history?.prices && message.history?.times) {
                                                                                                                                                                                                                                                                                                                                          const prices = message.history.prices;
                                                                                                                                                                                                                                                                                                                                                const times = message.history.times;

                                                                                                                                                                                                                                                                                                                                                      const buffer = history.get(symbol);
                                                                                                                                                                                                                                                                                                                                                            buffer.length = 0;

                                                                                                                                                                                                                                                                                                                                                                  const start = Math.max(0, prices.length - 1000);

                                                                                                                                                                                                                                                                                                                                                                        for (let i = start; i < prices.length; i++) {
                                                                                                                                                                                                                                                                                                                                                                                const quote = Number(prices[i]);

                                                                                                                                                                                                                                                                                                                                                                                        buffer.push({
                                                                                                                                                                                                                                                                                                                                                                                                  symbol,
                                                                                                                                                                                                                                                                                                                                                                                                            quote,
                                                                                                                                                                                                                                                                                                                                                                                                                      epoch: Number(times[i]),
                                                                                                                                                                                                                                                                                                                                                                                                                                pip_size: pipSize,
                                                                                                                                                                                                                                                                                                                                                                                                                                          digit: lastDigit(quote, pipSize),
                                                                                                                                                                                                                                                                                                                                                                                                                                                    received_at: Date.now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        broadcast({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                type: "history",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        symbol,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                count: buffer.length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        data: buffer
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (message.tick) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const tick = message.tick;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  saveTick(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          tick.symbol,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  tick.quote,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          tick.epoch,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  tick.pip_size ?? pipSize
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                deriv.on("error", error => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.error("Deriv connection error:", error.message);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        deriv.on("close", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            connected = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                reconnects++;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    broadcast({ type: "status", connected: false });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.log("Deriv disconnected. Reconnecting...");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            reconnectTimer = setTimeout(() => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  reconnectDelay = Math.min(reconnectDelay * 2, 30000);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        connectDeriv();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }, reconnectDelay);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const server = http.createServer((req, res) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                res.setHeader("Access-Control-Allow-Origin", "*");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  res.setHeader("Content-Type", "application/json");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (req.url === "/health") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        res.writeHead(200);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            res.end(JSON.stringify({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  service: "Neural Digit Ingestion",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        deriv_connected: connected,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              markets: MARKETS,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ticks: Object.fromEntries(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            [...history.entries()].map(([symbol, ticks]) => [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      symbol,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ticks.length
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    last_message_at: lastMessageAt,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          reconnects
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      res.writeHead(200);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        res.end(JSON.stringify({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            service: "Neural Digit Ingestion",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                status: "running",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    stream: "/stream",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        health: "/health"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const wss = new WebSocketServer({ noServer: true });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          server.on("upgrade", (req, socket, head) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (req.url !== "/stream") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                socket.destroy();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        wss.handleUpgrade(req, socket, head, client => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            wss.emit("connection", client, req);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              wss.on("connection", client => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                clients.add(client);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!ACCESS_KEY) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      authenticated.add(client);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          sendJSON(client, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                type: "snapshot",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      markets: Object.fromEntries(history)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                sendJSON(client, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      type: "auth_required"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              client.on("message", raw => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!ACCESS_KEY) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const message = JSON.parse(raw.toString());

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          message.type === "auth" &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  message.key === ACCESS_KEY
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                authenticated.add(client);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        sendJSON(client, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  type: "authenticated",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            markets: Object.fromEntries(history)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } else if (!authenticated.has(client)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  client.close(1008, "Authentication required");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  client.close(1008, "Invalid message");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          client.on("close", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              clients.delete(client);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  authenticated.delete(client);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    server.listen(PORT, "0.0.0.0", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      console.log(`Ingestion service running on port ${PORT}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.log(`Markets: ${MARKETS.join(", ")}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          connectDeriv();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          